function fetchAuth() {
  return new Promise(res => setTimeout(() => res('Token'), 1000));
}

async function login() {
  console.log('Logging in...');

  // Code waits here!
  const token = await fetchAuth(); 

  console.log('Success! Token: ' + token);
}
login();

